for (const [category, value] of Object.entries(categoryFallbacks)) {
  const [disciplineZh, disciplineEn, applications, roles, abilities, further, subjectCourses] = value;
  profiles.push([category, '.*', disciplineZh, disciplineEn, ...applications, ...roles, ...abilities, ...further, subjectCourses]);
}
profiles.push([null, '.*', '专业领域的理论与实践', 'discipline-specific theory and practice', '相关行业、专业服务、研究机构与公共部门', 'relevant industries, professional services, research organisations and the public sector', '专业助理、项目协调员、研究助理及相关行业岗位', 'professional associate, project coordinator, research assistant and related industry roles', '专业知识、研究分析、数字工具、沟通协作与项目实践', 'disciplinary knowledge, research and analysis, digital tools, communication, teamwork and applied projects', '本专业或相关交叉领域的硕士、博士或专业资格课程', 'postgraduate study or professional qualifications in this or a related interdisciplinary field', courses(['学科导论','Introduction to the Discipline'],['基础理论','Foundational Theory'],['研究与分析方法','Research and Analytical Methods'],['专业核心专题','Core Disciplinary Topics'],['行业应用与伦理','Industry Applications and Ethics'],['综合实践项目','Capstone Practice Project'])]);

const quote = value => value == null ? 'NULL' : `'${String(value).replaceAll("'", "''")}'`;
const rows = profiles.map((profile, index) => {
  const [category, pattern, disciplineZh, disciplineEn, applicationsZh, applicationsEn, rolesZh, rolesEn,
    abilitiesZh, abilitiesEn, furtherZh, furtherEn, subjectCourses] = profile;
  const flat = [index + 1, category, pattern, disciplineZh, disciplineEn, applicationsZh, applicationsEn,
    rolesZh, rolesEn, abilitiesZh, abilitiesEn, furtherZh, furtherEn,
    ...subjectCourses.flatMap(([zh, en]) => [zh, en])];
  return `  (${flat.map((value, column) => column === 0 ? String(value) : quote(value)).join(', ')})`;
}).join(',\n');

const sql = `-- Generated by scripts/generate-programme-content-migration.mjs.
-- Generated descriptions and study areas are supplementary editorial content, not official syllabi.
-- Existing nonblank programme descriptions and verified/manual detail sections are preserved.
WITH content_profiles(
 priority, category_code, name_pattern, discipline_zh, discipline_en,
 applications_zh, applications_en, roles_zh, roles_en, abilities_zh, abilities_en,
 further_zh, further_en,
 course_1_zh, course_1_en, course_2_zh, course_2_en, course_3_zh, course_3_en,
 course_4_zh, course_4_en, course_5_zh, course_5_en, course_6_zh, course_6_en
) AS (
 VALUES
${rows}
), matched AS (
 SELECT p.id AS programme_id,
        COALESCE(NULLIF(BTRIM(p.name_zh), ''), NULLIF(BTRIM(p.name_en), ''), p.programme_code) AS programme_name_zh,
        COALESCE(NULLIF(BTRIM(p.name_en), ''), NULLIF(BTRIM(p.name_zh), ''), p.programme_code) AS programme_name_en,
        cp.*
 FROM programmes p
 JOIN subject_categories c ON c.id = p.subject_category_id
 CROSS JOIN LATERAL (
   SELECT profile.* FROM content_profiles profile
   WHERE (profile.category_code IS NULL OR profile.category_code = c.code)
     AND CONCAT_WS(' ', p.name_zh, p.name_en) ~* profile.name_pattern
   ORDER BY profile.priority
   LIMIT 1
 ) cp
 WHERE p.status = 'PUBLISHED'
), descriptions AS (
 SELECT programme_id,
   programme_name_zh || '聚焦' || discipline_zh || '，结合' || applications_zh ||
     '等真实应用场景，帮助学生建立系统的专业知识、分析方法与实践能力。学习过程中通常重视' || abilities_zh ||
     '，并通过案例、实验、设计或研究项目理解该领域如何解决实际问题。具体课程名称、学分和考核方式以院校最新官方教学大纲为准。' AS description_zh,
   programme_name_en || ' focuses on ' || discipline_en || ', connecting academic foundations with applications in ' ||
     applications_en || '. The field develops ' || abilities_en ||
     ' through analysis, case work, laboratories, design or research projects. Exact modules, credits and assessment methods are determined by the university’s current official syllabus.' AS description_en
 FROM matched
), updated_descriptions AS (
 UPDATE programmes p
 SET description_zh = COALESCE(NULLIF(BTRIM(p.description_zh), ''), d.description_zh),
     description_en = COALESCE(NULLIF(BTRIM(p.description_en), ''), d.description_en),
     updated_at = CURRENT_TIMESTAMP
 FROM descriptions d
 WHERE p.id = d.programme_id
   AND (NULLIF(BTRIM(p.description_zh), '') IS NULL OR NULLIF(BTRIM(p.description_en), '') IS NULL)
 RETURNING p.id
), entries AS (
 SELECT programme_id, 'CAREER_OPPORTUNITIES'::varchar AS section_type,
   '专业前景'::varchar AS title_zh, 'Career opportunities'::varchar AS title_en,
   '行业应用：' || applications_zh || E'。\n\n具体就业岗位：' || roles_zh ||
     E'。\n\n核心能力：' || abilities_zh || E'。\n\n深造方向：' || further_zh ||
     E'。\n\n职业说明：岗位准入和发展取决于个人能力、实习经历、当地法规及专业认证要求，不构成就业承诺。' AS body_zh,
   'Industry applications: ' || applications_en || E'.\n\nPotential roles: ' || roles_en ||
     E'.\n\nCore capabilities: ' || abilities_en || E'.\n\nFurther study: ' || further_en ||
     E'.\n\nCareer note: Entry and progression depend on individual capability, experience, local regulation and any required professional accreditation; no employment outcome is guaranteed.' AS body_en,
   30 AS sort_order
 FROM matched
 UNION ALL
 SELECT programme_id, 'CURRICULUM', '专业课程', 'Programme curriculum',
   E'参考学习领域，非官方课程表\n' ||
   '01|' || course_1_zh || '|' || course_1_en || E'\n' ||
   '02|' || course_2_zh || '|' || course_2_en || E'\n' ||
   '03|' || course_3_zh || '|' || course_3_en || E'\n' ||
   '04|' || course_4_zh || '|' || course_4_en || E'\n' ||
   '05|' || course_5_zh || '|' || course_5_en || E'\n' ||
   '06|' || course_6_zh || '|' || course_6_en || E'\n' ||
   '说明：以上内容根据专业名称与学科方向整理，用于帮助理解可能涉及的知识领域，不是院校官方课程名称、学分、必修或选修安排；请以院校最新官方教学大纲为准。',
   E'Illustrative study areas, not an official module list\n' ||
   '01|' || course_1_en || '|' || course_1_zh || E'\n' ||
   '02|' || course_2_en || '|' || course_2_zh || E'\n' ||
   '03|' || course_3_en || '|' || course_3_zh || E'\n' ||
   '04|' || course_4_en || '|' || course_4_zh || E'\n' ||
   '05|' || course_5_en || '|' || course_5_zh || E'\n' ||
   '06|' || course_6_en || '|' || course_6_zh || E'\n' ||
   'Note: These areas are inferred from the programme title and discipline to explain likely fields of study. They are not official module names, credits or compulsory/elective arrangements. Refer to the university’s current official syllabus.',
   40
 FROM matched
)
INSERT INTO programme_detail_sections (
 programme_id, section_type, title_zh, title_en, body_zh, body_en,
 sort_order, source_url, source_checked_at, status, created_at, updated_at
)
SELECT programme_id, section_type, title_zh, title_en, body_zh, body_en,
       sort_order, NULL, NULL, 'PUBLISHED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM entries
ON CONFLICT (programme_id, section_type) DO UPDATE
SET title_zh = COALESCE(NULLIF(BTRIM(programme_detail_sections.title_zh), ''), EXCLUDED.title_zh),
    title_en = COALESCE(NULLIF(BTRIM(programme_detail_sections.title_en), ''), EXCLUDED.title_en),
    body_zh = CASE
      WHEN programme_detail_sections.source_url IS NULL AND (
        programme_detail_sections.body_zh LIKE '参考课程结构（非院校官方科目表）%'
        OR programme_detail_sections.body_zh LIKE '%核心竞争力：建议通过专业技能、跨学科协作%'
      ) THEN EXCLUDED.body_zh
      ELSE COALESCE(NULLIF(BTRIM(programme_detail_sections.body_zh), ''), EXCLUDED.body_zh)
    END,
    body_en = CASE
      WHEN programme_detail_sections.source_url IS NULL AND (
        programme_detail_sections.body_zh LIKE '参考课程结构（非院校官方科目表）%'
        OR programme_detail_sections.body_zh LIKE '%核心竞争力：建议通过专业技能、跨学科协作%'
      ) THEN EXCLUDED.body_en
      ELSE COALESCE(NULLIF(BTRIM(programme_detail_sections.body_en), ''), EXCLUDED.body_en)
    END,
    sort_order = programme_detail_sections.sort_order,
    status = 'PUBLISHED',
    updated_at = CURRENT_TIMESTAMP
WHERE NULLIF(BTRIM(programme_detail_sections.body_zh), '') IS NULL
   OR NULLIF(BTRIM(programme_detail_sections.body_en), '') IS NULL
   OR (
     programme_detail_sections.source_url IS NULL AND (
       programme_detail_sections.body_zh LIKE '参考课程结构（非院校官方科目表）%'
       OR programme_detail_sections.body_zh LIKE '%核心竞争力：建议通过专业技能、跨学科协作%'
     )
   );

DO $$
BEGIN
 IF EXISTS (
   SELECT 1 FROM programmes p
   WHERE p.status = 'PUBLISHED'
     AND (NULLIF(BTRIM(p.description_zh), '') IS NULL OR NULLIF(BTRIM(p.description_en), '') IS NULL)
 ) THEN RAISE EXCEPTION 'Published programme description backfill is incomplete'; END IF;
 IF EXISTS (
   SELECT 1 FROM programmes p
   WHERE p.status = 'PUBLISHED'
     AND NOT EXISTS (
       SELECT 1 FROM programme_detail_sections s
       WHERE s.programme_id = p.id AND s.section_type = 'CAREER_OPPORTUNITIES'
         AND s.status = 'PUBLISHED' AND NULLIF(BTRIM(s.body_zh), '') IS NOT NULL
     )
 ) THEN RAISE EXCEPTION 'Published programme career backfill is incomplete'; END IF;
 IF EXISTS (
   SELECT 1 FROM programmes p
   WHERE p.status = 'PUBLISHED'
     AND NOT EXISTS (
       SELECT 1 FROM programme_detail_sections s
       WHERE s.programme_id = p.id AND s.section_type = 'CURRICULUM'
         AND s.status = 'PUBLISHED' AND NULLIF(BTRIM(s.body_zh), '') IS NOT NULL
     )
 ) THEN RAISE EXCEPTION 'Published programme curriculum backfill is incomplete'; END IF;
END $$;
`;

const here = dirname(fileURLToPath(import.meta.url));
const output = resolve(here, '../backend/src/main/resources/db/migration/V33__enrich_published_programme_content.sql');
writeFileSync(output, sql, 'utf8');
console.log(`Wrote ${output} with ${profiles.length} content profiles.`);

export { profiles };
